const saida = [];
$input.all().forEach((item, email) => {
  const cfg = item.json.config;
  const senhas = ['', ...String(cfg.senhas_pdf || '').split(',').map((s) => s.trim()).filter(Boolean)];
  const pdfs = Object.entries(item.binary || {}).filter(([, b]) => /pdf/i.test(b.mimeType || '') || /\.pdf$/i.test(b.fileName || ''));
  if (!pdfs.length) {
    saida.push({ json: { email, arquivo: '', senha: '' }, pairedItem: email });
    return;
  }
  for (const [, binario] of pdfs) {
    for (const senha of senhas) {
      saida.push({ json: { email, arquivo: binario.fileName || 'anexo.pdf', senha }, binary: { pdf: binario }, pairedItem: email });
    }
  }
});
return saida;

const emails = $('⚙️ Configuração').all();
const tentativas = $('📎 PDFs').all();
const textos = $input.all();
const cfg = emails[0].json.config;
const porEmail = emails.map(() => ({ pdfs: {}, falhas: new Set() }));
tentativas.forEach((tentativa, i) => {
  const { email, arquivo } = tentativa.json;
  if (!arquivo) return;
  const texto = (textos[i] && textos[i].json && textos[i].json.text) || '';
  if (texto.trim()) {
    porEmail[email].pdfs[arquivo] = porEmail[email].pdfs[arquivo] || texto;
  } else {
    porEmail[email].falhas.add(arquivo);
  }
});
const SISTEMA = "Você lê e-mails de cobrança brasileiros (contas de consumo, boletos, faturas, Pix) e extrai os dados para pagamento. Responda só com o JSON pedido. Se o e-mail não for uma cobrança, devolva e_cobranca false e a lista vazia. Um e-mail normalmente traz uma única conta, mesmo com vários anexos (boleto, nota fiscal, demonstrativo, extrato, contrato, comprovante): use o documento que tem o código de pagamento e ignore os demais; não crie conta a partir de nota fiscal, demonstrativo ou comprovante. Só devolva mais de uma conta se houver mais de um código de pagamento diferente. Para cada conta: conta é um nome curto e reconhecível (ex.: Energia, Internet, Condomínio, Cartão Nubank); beneficiario é quem recebe; valor é o total a pagar em reais, número com ponto decimal (0 se não aparecer); vencimento no formato AAAA-MM-DD (vazio se não aparecer); linha_digitavel com os dígitos exatamente como estão no documento (vazio se não houver); pix_copia_e_cola exatamente como está, sem espaços nem quebras (vazio se não houver); observacoes curtas (ex.: conta em débito automático, parcela 3 de 10); anexo é o nome do arquivo de onde saiu o código (vazio se veio do corpo do e-mail). Nunca invente códigos: copie só o que estiver no texto.";
const ESQUEMA = {"type": "object", "properties": {"e_cobranca": {"type": "boolean"}, "contas": {"type": "array", "items": {"type": "object", "properties": {"conta": {"type": "string"}, "beneficiario": {"type": "string"}, "valor": {"type": "number"}, "vencimento": {"type": "string"}, "linha_digitavel": {"type": "string"}, "pix_copia_e_cola": {"type": "string"}, "observacoes": {"type": "string"}, "anexo": {"type": "string"}}, "required": ["conta", "beneficiario", "valor", "vencimento", "linha_digitavel", "pix_copia_e_cola", "observacoes", "anexo"], "additionalProperties": false}}}, "required": ["e_cobranca", "contas"], "additionalProperties": false};
return emails.map((item, email) => {
  const e = item.json;
  const corpo = String(e.text || '').trim() || String(e.html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const pontos = (texto) => {
    let p = 0;
    if (/\d{5}[.\s]?\d{5}\s?\d{5}[.\s]?\d{6}\s?\d{5}[.\s]?\d{6}\s?\d\s?\d{14}/.test(texto)) p += 10;
    if (/\b8\d{10}[-\s]?\d\s?\d{11}[-\s]?\d/.test(texto)) p += 10;
    if (/000201\S*br\.gov\.bcb\.pix/i.test(texto)) p += 10;
    if (/linha digit[aá]vel|pag[aá]vel|c[oó]digo de barras|boleto|pix/i.test(texto)) p += 3;
    if (/vencimento/i.test(texto)) p += 1;
    if (/nota fiscal|danfe|demonstrativo|extrato|contrato|comprovante/i.test(texto)) p -= 2;
    return p;
  };
  let restante = 60000;
  const anexos = Object.entries(porEmail[email].pdfs)
    .sort(([, a], [, b]) => pontos(b) - pontos(a))
    .map(([nome, texto]) => {
      const parte = texto.slice(0, Math.min(20000, Math.max(restante, 0)));
      restante -= parte.length;
      return parte ? `--- anexo ${nome} ---\n${parte}` : `--- anexo ${nome} (não incluído: limite de texto) ---`;
    })
    .join('\n\n');
  const falhas = [...porEmail[email].falhas].filter((nome) => !porEmail[email].pdfs[nome]);
  const conteudo = [
    `Assunto: ${e.subject || ''}`,
    `De: ${(e.from && e.from.text) || ''}`,
    `Data: ${e.date || ''}`,
    '',
    corpo.slice(0, 20000),
    anexos ? '\n' + anexos : '',
  ].join('\n');
  return {
    json: {
      email,
      assunto: e.subject || '',
      data: e.date || '',
      anexos_sem_leitura: falhas,
      pedido: {
        model: cfg.modelo,
        max_tokens: 4000,
        output_config: { effort: cfg.esforco, format: { type: 'json_schema', schema: ESQUEMA } },
        system: SISTEMA,
        messages: [{ role: 'user', content: conteudo }],
      },
    },
    pairedItem: email,
  };
});

const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

function mod10(numero) {
  let soma = 0;
  let peso = 2;
  for (let i = numero.length - 1; i >= 0; i--) {
    let parcial = Number(numero[i]) * peso;
    if (parcial > 9) parcial = Math.floor(parcial / 10) + (parcial % 10);
    soma += parcial;
    peso = peso === 2 ? 1 : 2;
  }
  return (10 - (soma % 10)) % 10;
}

function mod11(numero, arrecadacao) {
  let soma = 0;
  let peso = 2;
  for (let i = numero.length - 1; i >= 0; i--) {
    soma += Number(numero[i]) * peso;
    peso = peso === 9 ? 2 : peso + 1;
  }
  const resto = soma % 11;
  if (arrecadacao) return resto === 0 || resto === 1 ? 0 : 11 - resto;
  const dv = 11 - resto;
  return dv === 0 || dv === 10 || dv === 11 ? 1 : dv;
}

function vencimentoPorFator(fator, referencia) {
  if (!fator) return '';
  const dia = 24 * 60 * 60 * 1000;
  const candidatos = [Date.UTC(1997, 9, 7) + fator * dia];
  if (fator >= 1000) candidatos.push(Date.UTC(2025, 1, 22) + (fator - 1000) * dia);
  const alvo = referencia ? Date.parse(referencia) : Date.now();
  candidatos.sort((a, b) => Math.abs(a - alvo) - Math.abs(b - alvo));
  return new Date(candidatos[0]).toISOString().slice(0, 10);
}

function conferirLinha(linha, referencia) {
  const d = String(linha || '').replace(/\D/g, '');
  if (!d) return { ok: false, motivo: '' };
  if (d.length === 47) {
    const campos = [[0, 9], [10, 20], [21, 31]];
    for (const [ini, fim] of campos) {
      if (mod10(d.slice(ini, fim)) !== Number(d[fim])) return { ok: false, motivo: 'dígito de um campo da linha digitável não confere' };
    }
    const barras = d.slice(0, 4) + d[32] + d.slice(33, 47) + d.slice(4, 9) + d.slice(10, 20) + d.slice(21, 31);
    if (mod11(barras.slice(0, 4) + barras.slice(5), false) !== Number(barras[4])) return { ok: false, motivo: 'dígito geral do boleto não confere' };
    return { ok: true, digitos: d, valor: Number(d.slice(37, 47)) / 100, vencimento: vencimentoPorFator(Number(d.slice(33, 37)), referencia) };
  }
  if (d.length === 48 && d[0] === '8') {
    const id = d[2];
    const blocos = [0, 12, 24, 36].map((i) => d.slice(i, i + 12));
    for (const bloco of blocos) {
      const dv = id === '6' || id === '7' ? mod10(bloco.slice(0, 11)) : mod11(bloco.slice(0, 11), true);
      if (dv !== Number(bloco[11])) return { ok: false, motivo: 'dígito de um bloco da conta não confere' };
    }
    const barras = blocos.map((b) => b.slice(0, 11)).join('');
    const valor = id === '6' || id === '8' ? Number(barras.slice(4, 15)) / 100 : null;
    return { ok: true, digitos: d, valor, vencimento: '' };
  }
  return { ok: false, motivo: `linha digitável com ${d.length} dígitos (esperado 47 ou 48)` };
}

function crc16(texto) {
  let crc = 0xffff;
  for (const byte of Buffer.from(texto, 'utf8')) {
    crc ^= byte << 8;
    for (let i = 0; i < 8; i++) crc = crc & 0x8000 ? ((crc << 1) ^ 0x1021) & 0xffff : (crc << 1) & 0xffff;
  }
  return crc.toString(16).toUpperCase().padStart(4, '0');
}

function conferirPix(pix) {
  const p = String(pix || '').trim();
  if (!p) return { ok: false, motivo: '' };
  const m = p.match(/^(.*6304)([0-9A-Fa-f]{4})$/s);
  if (!p.startsWith('000201') || !m) return { ok: false, motivo: 'Pix copia e cola fora do formato' };
  if (crc16(m[1]) !== m[2].toUpperCase()) return { ok: false, motivo: 'CRC do Pix não confere' };
  return { ok: true, codigo: p };
}

function reais(valor) {
  if (valor === null || valor === undefined || Number.isNaN(Number(valor))) return 'R$ ?';
  return 'R$ ' + Number(valor).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
}

function brData(iso) {
  const [a, m, d] = String(iso).split('-');
  return d && m && a ? `${d}/${m}/${a}` : iso;
}

function titulo(mes) {
  const [a, m] = mes.split('-');
  return `# Contas a pagar · ${MESES[Number(m) - 1]} de ${a}`;
}

const pedidos = $('🧾 Montar pedido').all();
const meses = {};
const avisos = [];
function adicionar(mes, bloco, chave, resumo) {
  meses[mes] = meses[mes] || { blocos: [], chaves: [], resumos: [] };
  meses[mes].blocos.push(bloco);
  meses[mes].chaves.push(chave);
  meses[mes].resumos.push(resumo);
}
$input.all().forEach((resposta, i) => {
  const pedido = pedidos[i].json;
  const recebido = pedido.data ? new Date(pedido.data) : new Date();
  const local = DateTime.fromJSDate(recebido, { zone: $now.zoneName });
  const mesRecebido = local.toFormat('yyyy-MM');
  const dataRecebido = local.toFormat('dd/MM/yyyy');
  const origem = `recebido em ${dataRecebido} · e-mail "${String(pedido.assunto).replace(/"/g, "'")}"`;
  const r = resposta.json;
  const texto = r && Array.isArray(r.content) ? (r.content.find((b) => b.type === 'text') || {}).text : '';
  let dados = null;
  try { dados = JSON.parse(texto); } catch (erro) { dados = null; }
  if (!dados || r.stop_reason === 'refusal' || r.stop_reason === 'max_tokens') {
    const motivo = r && r.error ? (r.error.message || JSON.stringify(r.error)) : (r && r.stop_reason) || 'resposta inválida';
    adicionar(mesRecebido, `- [ ] ⚠️ revisar: e-mail não lido pela IA (${motivo})\n  - ${origem}`, `falha:${pedido.assunto}:${pedido.data}`, `⚠️ e-mail "${pedido.assunto}" não lido pela IA`);
    return;
  }
  if (!dados.e_cobranca || !dados.contas.length) return;
  for (const c of dados.contas) {
    const problemas = [];
    const linha = conferirLinha(c.linha_digitavel, recebido.toISOString());
    const pix = conferirPix(c.pix_copia_e_cola);
    if (c.linha_digitavel && !linha.ok) problemas.push(linha.motivo);
    if (c.pix_copia_e_cola && !pix.ok) problemas.push(pix.motivo);
    if (!c.linha_digitavel && !c.pix_copia_e_cola) problemas.push('sem código de pagamento');
    let valor = Number(c.valor) || null;
    let vencimento = /^\d{4}-\d{2}-\d{2}$/.test(c.vencimento) ? c.vencimento : '';
    if (linha.ok && linha.valor && valor && Math.abs(linha.valor - valor) > 0.009) problemas.push(`valor no código: ${reais(linha.valor)}`);
    if (linha.ok && linha.valor && !valor) valor = linha.valor;
    if (linha.ok && linha.vencimento && !vencimento) vencimento = linha.vencimento;
    if (linha.ok && linha.vencimento && vencimento && linha.vencimento !== vencimento) problemas.push(`vencimento no código: ${brData(linha.vencimento)}`);
    const mes = vencimento ? vencimento.slice(0, 7) : mesRecebido;
    const alerta = problemas.length ? ` · ⚠️ revisar (${problemas.join('; ')})` : '';
    const venc = vencimento ? ` · vence 📅 ${vencimento}` : ' · sem vencimento';
    const linhas = [`- [ ] ${c.conta} · ${reais(valor)}${venc}${alerta}`];
    if (c.linha_digitavel) linhas.push(`  - Boleto: \`${linha.ok ? linha.digitos : c.linha_digitavel}\``);
    if (c.pix_copia_e_cola) linhas.push(`  - Pix: \`${c.pix_copia_e_cola.trim()}\``);
    const detalhes = [c.beneficiario && `Beneficiário: ${c.beneficiario}`, c.observacoes, c.anexo && `anexo ${c.anexo}`, origem].filter(Boolean).join(' · ');
    linhas.push(`  - ${detalhes}`);
    const chave = (linha.ok && linha.digitos) || (c.pix_copia_e_cola || '').trim() || `${c.conta}:${valor}:${vencimento}`;
    adicionar(mes, linhas.join('\n'), chave, `${alerta ? '⚠️' : '📄'} ${c.conta} · ${reais(valor)}${vencimento ? ' · vence ' + brData(vencimento) : ''}`);
  }
  if (pedido.anexos_sem_leitura.length) avisos.push(`PDF sem leitura (senha?): ${pedido.anexos_sem_leitura.join(', ')}`);
});
return Object.entries(meses).map(([mes, m]) => ({ json: { mes, titulo: titulo(mes), ...m, avisos } }));

const novos = $('✅ Conferir').all();
return $input.all().map((item, i) => {
  const n = novos[i].json;
  let atual = typeof item.json.conteudo === 'string' ? item.json.conteudo : '';
  if (!atual.trim()) atual = `${n.titulo}\n`;
  const adicionados = [];
  const resumos = [];
  n.blocos.forEach((bloco, j) => {
    const chave = n.chaves[j];
    if (chave && atual.includes(chave)) return;
    if (chave.startsWith('falha:') && atual.includes(bloco)) return;
    adicionados.push(bloco);
    resumos.push(n.resumos[j]);
    atual += '\n' + chave;
  });
  const base = typeof item.json.conteudo === 'string' && item.json.conteudo.trim() ? item.json.conteudo : `${n.titulo}\n`;
  const conteudo = base.replace(/\s*$/, '\n') + (adicionados.length ? '\n' + adicionados.join('\n') + '\n' : '');
  return { json: { mes: n.mes, conteudo, adicionados: adicionados.length, resumos, avisos: n.avisos } };
});

const atualizados = $('📝 Atualizar arquivo').all();
const resumos = atualizados.flatMap((item) => item.json.resumos);
const avisos = [...new Set(atualizados.flatMap((item) => item.json.avisos))];
if (!$('⚙️ Configuração').first().json.config.avisar_discord || (!resumos.length && !avisos.length)) return [];
const linhas = ['💸 **Contas a pagar**', ...resumos, ...avisos.map((a) => `⚠️ ${a}`)];
return [{ json: { mensagem: linhas.join('\n').slice(0, 1900) } }];
